// Package vtt checks a spell's `vtt` block against ttrpg-api/schemas/vtt_spell.v1.schema.json and
// fills in its defaults.
//
// Filling in defaults matters: py_dnd stores the block the way Pydantic dumps it, with every field
// present, and the database's generated columns (activation_amount, range_feet, ...) read those
// values. Expand produces the same document, so either API stores the same row.
//
// The schema is generated by Pydantic and uses a small subset of JSON Schema: type, properties,
// required, additionalProperties, items, anyOf, $ref, enum, const, default, minItems and
// minProperties. That subset is what this walker handles. Any other keyword fails at startup.
package vtt

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"fmt"
	"math"
	"reflect"
	"slices"
	"strings"
)

// schemaJSON is a copy of ttrpg-api/schemas/vtt_spell.v1.schema.json (go:embed can't reach outside
// the module). `go generate ./internal/vtt` refreshes it.
//
//go:generate cp ../../../schemas/vtt_spell.v1.schema.json vtt_spell.v1.schema.json
//go:embed vtt_spell.v1.schema.json
var schemaJSON []byte

type node = map[string]any

// Schema is a loaded VTT schema.
type Schema struct {
	root node
	defs map[string]node
}

// keywords this walker understands; annotations are ignored
var keywords = []string{
	"type", "properties", "required", "additionalProperties", "items", "anyOf", "$ref", "enum", "const",
	"default", "minItems", "minProperties", "title", "description", "$schema", "$id", "$defs",
}

// Load parses the embedded schema.
func Load() (*Schema, error) {
	var root node
	decoder := json.NewDecoder(bytes.NewReader(schemaJSON))
	decoder.UseNumber()
	if err := decoder.Decode(&root); err != nil {
		return nil, fmt.Errorf("vtt schema: %w", err)
	}
	s := &Schema{root: root, defs: map[string]node{}}
	if defs, ok := root["$defs"].(node); ok {
		for name, def := range defs {
			s.defs[name] = def.(node)
		}
	}
	if err := checkKeywords(root, "#"); err != nil {
		return nil, err
	}
	return s, nil
}

// MustLoad is Load for startup.
func MustLoad() *Schema {
	s, err := Load()
	if err != nil {
		panic(err)
	}
	return s
}

func checkKeywords(n node, at string) error {
	for key, value := range n {
		switch key {
		case "properties", "$defs":
			for name, child := range value.(node) {
				if err := checkKeywords(child.(node), at+"/"+key+"/"+name); err != nil {
					return err
				}
			}
			continue
		case "default", "enum", "const", "required":
			continue
		}
		if !slices.Contains(keywords, key) {
			return fmt.Errorf("vtt schema: %s uses %q, which internal/vtt doesn't handle", at, key)
		}
		switch child := value.(type) {
		case node:
			if err := checkKeywords(child, at+"/"+key); err != nil {
				return err
			}
		case []any:
			for i, item := range child {
				if itemNode, ok := item.(node); ok {
					if err := checkKeywords(itemNode, fmt.Sprintf("%s/%s/%d", at, key, i)); err != nil {
						return err
					}
				}
			}
		}
	}
	return nil
}

// Expand checks v (decoded with UseNumber) and returns it with every default filled in.
func (s *Schema) Expand(v any) (any, error) {
	return s.expand(s.root, v, "vtt")
}

func (s *Schema) resolve(n node) node {
	for {
		ref, ok := n["$ref"].(string)
		if !ok {
			return n
		}
		n = s.defs[strings.TrimPrefix(ref, "#/$defs/")]
	}
}

func (s *Schema) expand(n node, v any, path string) (any, error) {
	n = s.resolve(n)
	if options, ok := n["anyOf"].([]any); ok {
		var firstErr error
		for _, option := range options {
			out, err := s.expand(option.(node), v, path)
			if err == nil {
				return out, nil
			}
			if firstErr == nil {
				firstErr = err
			}
		}
		return nil, firstErr
	}
	if want, ok := n["const"]; ok && !equal(want, v) {
		return nil, fmt.Errorf("%s: must be %v", path, want)
	}
	if allowed, ok := n["enum"].([]any); ok && !slices.ContainsFunc(allowed, func(a any) bool { return equal(a, v) }) {
		return nil, fmt.Errorf("%s: must be one of %v", path, allowed)
	}
	switch n["type"] {
	case "object":
		return s.object(n, v, path)
	case "array":
		return s.array(n, v, path)
	case "string":
		if _, ok := v.(string); !ok {
			return nil, fmt.Errorf("%s: must be a string", path)
		}
	case "integer":
		number, ok := v.(json.Number)
		if !ok {
			return nil, fmt.Errorf("%s: must be an integer", path)
		}
		if _, err := number.Int64(); err != nil {
			f, err := number.Float64()
			if err != nil || f != math.Trunc(f) {
				return nil, fmt.Errorf("%s: must be an integer", path)
			}
			return json.Number(fmt.Sprintf("%d", int64(f))), nil
		}
	case "number":
		if _, ok := v.(json.Number); !ok {
			return nil, fmt.Errorf("%s: must be a number", path)
		}
	case "boolean":
		if _, ok := v.(bool); !ok {
			return nil, fmt.Errorf("%s: must be true or false", path)
		}
	case "null":
		if v != nil {
			return nil, fmt.Errorf("%s: must be null", path)
		}
	}
	return v, nil
}

func (s *Schema) object(n node, v any, path string) (any, error) {
	in, ok := v.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("%s: must be an object", path)
	}
	properties, _ := n["properties"].(node)
	required, _ := n["required"].([]any)
	out := make(map[string]any, len(properties)+len(in))
	for name, raw := range properties {
		property := raw.(node)
		value, present := in[name]
		if !present {
			def, hasDefault := property["default"]
			if !hasDefault {
				if slices.Contains(required, any(name)) {
					return nil, fmt.Errorf("%s.%s: field required", path, name)
				}
				continue
			}
			value = def // Pydantic validates nested defaults too, which fills theirs in
		}
		expanded, err := s.expand(property, value, path+"."+name)
		if err != nil {
			return nil, err
		}
		out[name] = expanded
	}
	for name, value := range in {
		if _, known := properties[name]; known {
			continue
		}
		switch extra := n["additionalProperties"].(type) {
		case bool:
			if !extra {
				return nil, fmt.Errorf("%s.%s: extra field not permitted", path, name)
			}
			out[name] = value
		case node:
			expanded, err := s.expand(extra, value, path+"."+name)
			if err != nil {
				return nil, err
			}
			out[name] = expanded
		default:
			out[name] = value
		}
	}
	if minimum, ok := n["minProperties"].(json.Number); ok {
		if want, _ := minimum.Int64(); int64(len(out)) < want {
			return nil, fmt.Errorf("%s: needs at least %d field(s)", path, want)
		}
	}
	return out, nil
}

func (s *Schema) array(n node, v any, path string) (any, error) {
	in, ok := v.([]any)
	if !ok {
		return nil, fmt.Errorf("%s: must be a list", path)
	}
	if minimum, ok := n["minItems"].(json.Number); ok {
		if want, _ := minimum.Int64(); int64(len(in)) < want {
			return nil, fmt.Errorf("%s: needs at least %d item(s)", path, want)
		}
	}
	items, hasItems := n["items"].(node)
	out := make([]any, len(in))
	for i, item := range in {
		if !hasItems {
			out[i] = item
			continue
		}
		expanded, err := s.expand(items, item, fmt.Sprintf("%s[%d]", path, i))
		if err != nil {
			return nil, err
		}
		out[i] = expanded
	}
	return out, nil
}

// equal compares JSON values, numbers by value.
func equal(a, b any) bool {
	an, aNum := a.(json.Number)
	bn, bNum := b.(json.Number)
	if aNum && bNum {
		af, _ := an.Float64()
		bf, _ := bn.Float64()
		return af == bf
	}
	return reflect.DeepEqual(a, b)
}
